ator.test.js (41 tests): financial calculations\n  - category.test.js (31 tests): duration and date formatting\n  - storage.test.js (32 tests): deep merge, state structure\n  - branding.test.js (24 tests): defaults and validation\n  - validator.test.js (18 tests): payment plan validation\n- Add vitest.config.js with jsdom environment\n- Update package.json with test dependencies\n\nCo-Authored-By: Claude Opus 4.5 <noreply@anthropic.com>","tree":{"sha":"8ca87fb3f8d740d9a09ac254c95d7a39811c3dad","url":"https://api.github.com/repos/Snoopiam/saleshub/git/trees/8ca87fb3f8d740d9a09ac254c95d7a39811c3dad"},"url":"https://api.github.com/repos/Snoopiam/saleshub/git/commits/1b09babae6222e98bcec30d0578664066857a274","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/186879703?v=4","events_url":"https://api.github.com/users/Snoopiam/events{/privacy}","followers_url":"https://api.github.com/users/Snoopiam/followers","following_url":"https://api.github.com/users/Snoopiam/following{/other_user}","gists_url":"https://api.github.com/users/Snoopiam/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Snoopiam","id":186879703,"login":"Snoopiam","node_id":"U_kgDOCyOO1w","organizations_url":"https://api.github.com/users/Snoopiam/orgs","received_events_url":"https://api.github.com/users/Snoopiam/received_events","repos_url":"https://api.github.com/users/Snoopiam/repos","site_admin":false,"starred_url":"https://api.github.com/users/Snoopiam/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Snoopiam/subscriptions","type":"User","url":"https://api.github.com/users/Snoopiam","user_view_type":"public"},"html_url":"https://github.com/Snoopiam/saleshub/commit/1b09babae6222e98bcec30d0578664066857a274","node_id":"C_kwDOQzkRutoAKDFiMDliYWJhZTYyMjJlOThiY2VjMzBkMDU3ODY2NDA2Njg1N2EyNzQ","parents":[{"html_url":"https://github.com/Snoopiam/saleshub